/* Local prototype authentication. No real identity provider, email or server security boundary. */
const AUTH_KEY='clc-accounts-v1',AUTH_SESSION_KEY='clc-role-sessions-v1';
const AUTH_ROUTES={customer:{login:'C01',signup:'C23',reset:'C24',security:'C25',home:'C02'},worker:{login:'W01',signup:'W19',reset:'W20',security:'W21',home:'W02'},admin:{login:'A38',signup:'A39',reset:'A40',security:'A41',home:'A01'}};
const AUTH_DEMOS=[{id:'CUSTOMER-DEMO',role:'customer',name:'Ada · demo customer',email:'customer@demo.chinalowcost.local',password:'DemoCustomer!26',recovery:'Customer-Recover-26',scope:'Customer'},{id:'WORKER-DEMO',role:'worker',name:'Chidi',email:'worker@demo.chinalowcost.local',password:'DemoWorker!26',recovery:'Worker-Recover-26',workerId:'ST-01',scope:'Fieldworker'},{id:'DELIVERY-DEMO',role:'worker',name:'Musa',email:'delivery@demo.chinalowcost.local',password:'DemoDelivery!26',recovery:'Delivery-Recover-26',workerId:'ST-02',scope:'Delivery'},{id:'ADMIN-DEMO',role:'admin',name:'Manager',email:'admin@demo.chinalowcost.local',password:'DemoAdmin!26',recovery:'Admin-Recover-26',scope:'Manager'},{id:'REVIEWER-DEMO',role:'admin',name:'Catalog reviewer',email:'reviewer@demo.chinalowcost.local',password:'DemoReview!26',recovery:'Reviewer-Recover-26',scope:'Catalog reviewer'}];
let authDatabase={users:[],invitations:[]},authSessions={},authBooted=false,authBootError='',authOneTimeRecovery='',authReturnTo={},authAttempts={};
let authPendingSelection=null;
const authRenderBase=render,authCustomerBase=customerPage,authWorkerBase=workerPage,authAdminBase=adminPage,authShellBase=shell;
const AUTH_CUSTOMER_FIELDS=['address','cart','quote','paid','transfer','order','orderSnapshot','promoCode','quoteAccepted','returnRequested','marketing','messages','mode','selected','qty'];
const authRoleForPage=p=>p.Application.toLowerCase();
const authCopy=value=>JSON.parse(JSON.stringify(value));
const authSaveDatabase=()=>{try{localStorage.setItem(AUTH_KEY,JSON.stringify(authDatabase));}catch{}};
const authSaveSessions=()=>{try{sessionStorage.setItem(AUTH_SESSION_KEY,JSON.stringify(authSessions));}catch{}};
function authHex(bytes){return Array.from(bytes,b=>b.toString(16).padStart(2,'0')).join('');}
function authRandom(length=16){return authHex(crypto.getRandomValues(new Uint8Array(length)));}
async function authHash(value,salt){const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(value),'PBKDF2',false,['deriveBits']);const bytes=Uint8Array.from(salt.match(/../g),x=>parseInt(x,16));return authHex(new Uint8Array(await crypto.subtle.deriveBits({name:'PBKDF2',salt:bytes,iterations:120000,hash:'SHA-256'},key,256)));}
function authPasswordError(p){return p.length<10||!/[a-z]/.test(p)||!/[A-Z]/.test(p)||!/[0-9]/.test(p)?'Use at least 10 characters with uppercase, lowercase and a number.':'';}
const authNormalizeRecovery=code=>code.replace(/[\s-]/g,'').toUpperCase();
async function authBuildUser(data,password,recovery){const salt=authRandom(),recoverySalt=authRandom();return {...data,salt,hash:await authHash(password,salt),recoverySalt,recoveryHash:await authHash(authNormalizeRecovery(recovery),recoverySalt),passwordVersion:1,createdAt:Date.now()};}
function authUser(role,email){return authDatabase.users.find(u=>u.role===role&&u.email===email.trim().toLowerCase());}
function authSession(role){const token=authSessions[role];if(!token||token.expiresAt<Date.now())return null;const user=authDatabase.users.find(u=>u.id===token.userId&&u.role===role&&u.passwordVersion===token.passwordVersion);if(!user)return null;if(role==='worker'){opsInit();const staff=state.ops.staff.find(w=>w.id===user.workerId);if(staff?.status!=='Active'||user.accessStatus==='Suspended')return null;}return user;}
function authIssueSession(user){authSessions[user.role]={userId:user.id,passwordVersion:user.passwordVersion,issuedAt:Date.now(),expiresAt:Date.now()+8*3600000,nonce:authRandom()};authSaveSessions();}
function authBlankRoom(user){const init=initialState();const room=Object.fromEntries(AUTH_CUSTOMER_FIELDS.map(k=>[k,init[k]??null]));room.address={...init.address,name:user?.name||'Guest · sample only',state:'Lagos',town:'Ikeja',area:'Ikeja',street:'Sample delivery address',phone:'Sample contact'};room.messages=[];return room;}
function authCaptureRoom(){return authCopy(Object.fromEntries(AUTH_CUSTOMER_FIELDS.map(k=>[k,state[k]??null])));}
function authInitializeRooms(){if(!state.authCustomerSpaces){state.authCustomerSpaces={'CUSTOMER-DEMO':authCaptureRoom()};state.authActiveCustomerId='CUSTOMER-DEMO';state.authOrderCustomerId='CUSTOMER-DEMO';}if(state.authActiveCustomerId)state.authCustomerSpaces[state.authActiveCustomerId]=authCaptureRoom();}
function authSwitchRoom(id){authInitializeRooms();if(state.authActiveCustomerId===id)return;state.authCustomerSpaces[state.authActiveCustomerId]=authCaptureRoom();if(state.order&&state.authActiveCustomerId!=='guest')state.authOrderCustomerId=state.authActiveCustomerId;const user=authDatabase.users.find(u=>u.id===id);const room=state.authCustomerSpaces[id]||authBlankRoom(user);Object.assign(state,authCopy(room));state.authActiveCustomerId=id;state.authCustomerSpaces[id]=authCopy(room);ensureCommerce();persist();}
function authScopeHome(role){const u=authSession(role);return role==='admin'&&u?.scope==='Catalog reviewer'?'A08':AUTH_ROUTES[role].home;}
function authPublicPage(id){return ['C01','C02','C03','C04','C05','C06','C07','C08','C17','C22','C23','C24','W01','W19','W20','A38','A39','A40'].includes(id);}
function authCanPage(user,id){if(user?.role!=='admin'||user.scope!=='Catalog reviewer')return true;return ['A07','A08','A24','A25','A35','A36','A38','A39','A40','A41'].includes(id);}
async function authInitialize(){try{if(typeof crypto==='undefined'||!crypto.subtle)throw Error('This browser cannot provide the local password hashing required by this prototype.');try{const stored=JSON.parse(localStorage.getItem(AUTH_KEY));if(stored?.users?.length)authDatabase=stored;}catch{}try{authSessions=JSON.parse(sessionStorage.getItem(AUTH_SESSION_KEY))||{};}catch{}for(const demo of AUTH_DEMOS){if(!authDatabase.users.some(u=>u.id===demo.id)){const {password,recovery,...data}=demo;authDatabase.users.push(await authBuildUser(data,password,recovery));}}authDatabase.invitations=[];authSaveDatabase();authInitializeRooms();authBooted=true;}catch(e){authBootError=e.message;}render();}
function authAudit(action,user){state.audit.unshift({action,actor:user.name+' · '+user.role,time:new Date().toLocaleTimeString('en-GB')});persist();}
async function authLoginValues(role,email,password){const key=role+':'+email.trim().toLowerCase(),attempt=authAttempts[key];if(attempt?.until>Date.now())return {ok:false,message:'Please wait one minute before trying again.'};const user=authUser(role,email);const valid=user&&await authHash(password,user.salt)===user.hash;if(!valid){const count=(attempt?.count||0)+1;authAttempts[key]={count,until:count>=5?Date.now()+60000:0};return {ok:false,message:'Email or password is incorrect for this application.'};}if(role==='worker'){opsInit();if(state.ops.staff.find(w=>w.id===user.workerId)?.status!=='Active')return {ok:false,message:'Your worker account is pending approval or suspended. An admin must activate it.'};}delete authAttempts[key];authIssueSession(user);if(role==='customer')authSwitchRoom(user.id);if(role==='worker')state.ops.workerId=user.workerId;if(role==='admin'){state.staffActor=user.scope;state.ops.reviewer=user.scope;}authAudit('Signed in to '+role+' app',user);return {ok:true,user};}
async function authLoginForm(role){const email=$('auth-email').value,password=$('auth-password').value;$('auth-status').textContent='Signing in…';try{const result=await authLoginValues(role,email,password);$('auth-password').value='';if(!result.ok){$('auth-status').textContent=result.message;return;}const target=authReturnTo[role]||authScopeHome(role);if(role==='customer')authRestoreSelection();delete authReturnTo[role];go(target);}catch{$('auth-status').textContent='Sign-in could not finish. Try again.';}}
function authLogout(role){authOneTimeRecovery='';const user=authSession(role);if(role==='worker'&&user){const w=state.ops.staff.find(w=>w.id===user.workerId);if(w){w.shift=false;opsDevicePositions.delete(w.id);}}if(role==='customer'){authInitializeRooms();state.authCustomerSpaces[state.authActiveCustomerId]=authCaptureRoom();}delete authSessions[role];authSaveSessions();persist();go(AUTH_ROUTES[role].login);toast('Signed out of the '+role+' application.');}
function authRestoreSelection(){if(authPendingSelection&&products.some(p=>p.id===authPendingSelection.sku)){state.selected=authPendingSelection.sku;state.qty=authPendingSelection.qty;state.mode=authPendingSelection.mode;}authPendingSelection=null;persist();}
async function authSignupValues(role,{name,email,password,confirm,invite,requestedRole}){email=email.trim().toLowerCase();if(!name.trim()||!/^\S+@\S+\.\S+$/.test(email))return {ok:false,message:'Enter a display name and valid sample email.'};const error=authPasswordError(password);if(error||password!==confirm)return {ok:false,message:error||'Passwords do not match.'};if(authUser(role,email))return {ok:false,message:'This email already has an account in this application.'};let invitation;if(role==='admin'){invitation=authDatabase.invitations.find(i=>i.code===invite?.trim()&&!i.used&&i.expiresAt>Date.now()&&i.email===email);if(!invitation)return {ok:false,message:'An unused invitation matching this email is required.'};}const id=role.toUpperCase()+'-'+authRandom(8),recovery=authRandom(12).toUpperCase().match(/.{1,4}/g).join('-');let workerId;if(role==='worker'){if(!['Catalog','Procurement','Delivery','Fieldworker'].includes(requestedRole))return {ok:false,message:'Choose a staff role to request.'};workerId='ST-'+authRandom(6);state.ops.staff.push({id:workerId,name:name.trim(),role:requestedRole,team:'Pending assignment',status:'Pending approval',region:'Lagos',town:'Ikeja',shift:false,lastSeen:null});}const user=await authBuildUser({id,role,name:name.trim(),email,workerId,scope:role==='admin'?invitation.scope:role==='worker'?requestedRole:'Customer'},password,recovery);authDatabase.users.push(user);if(invitation)invitation.used=true;authSaveDatabase();if(role==='customer'){state.authCustomerSpaces[id]=authBlankRoom(user);authIssueSession(user);authSwitchRoom(id);}authAudit('Created '+role+' account'+(role==='worker'?' pending staff approval':''),user);return {ok:true,user,recovery};}
async function authSignupForm(role){$('auth-status').textContent='Creating local demo account…';try{const result=await authSignupValues(role,{name:$('auth-name').value,email:$('auth-email').value,password:$('auth-password').value,confirm:$('auth-confirm').value,invite:$('auth-invite')?.value,requestedRole:$('auth-request-role')?.value});$('auth-password').value='';$('auth-confirm').value='';if(!result.ok){$('auth-status').textContent=result.message;return;}authOneTimeRecovery=result.recovery;openModal('Account created',`<p>${role==='worker'?'Your staff account is pending admin approval.':role==='admin'?'Your invitation has been accepted. Sign in to your admin account.':'Your customer account is ready.'}</p><p>Save this one-time local recovery code:</p><code class="auth-recovery-code">${esc(result.recovery)}</code><p class="muted">It is not stored as readable text. Use fictional details in this prototype.</p>${button('Continue',`$('modal').close();go('${role==='customer'?'C02':AUTH_ROUTES[role].login}')`)}`);}catch{$('auth-status').textContent='Account creation could not finish. Try again.';}}
async function authChangePassword(role,currentPassword,newPassword,confirm){const u=authSession(role);if(!u)return {ok:false,message:'Sign in to this application first.'};if(await authHash(currentPassword,u.salt)!==u.hash)return {ok:false,message:'Current password is incorrect.'};const error=authPasswordError(newPassword);if(error||newPassword!==confirm||newPassword===currentPassword)return {ok:false,message:error||'Use a matching new password different from the current one.'};u.salt=authRandom();u.hash=await authHash(newPassword,u.salt);u.passwordVersion++;authSaveDatabase();authIssueSession(u);authAudit('Changed account password',u);return {ok:true};}
async function authPasswordForm(role){$('auth-status').textContent='Updating password…';const result=await authChangePassword(role,$('auth-current').value,$('auth-new').value,$('auth-confirm').value);['auth-current','auth-new','auth-confirm'].forEach(id=>$(id).value='');$('auth-status').textContent=result.ok?'Password changed. Other sessions for this account must sign in again.':result.message;}
async function authResetValues(role,email,recovery,password,confirm){const u=authUser(role,email);const error=authPasswordError(password);if(error||password!==confirm)return {ok:false,message:error||'New passwords do not match.'};if(!u||await authHash(authNormalizeRecovery(recovery),u.recoverySalt)!==u.recoveryHash)return {ok:false,message:'Email or recovery code is incorrect for this application.'};u.salt=authRandom();u.hash=await authHash(password,u.salt);u.passwordVersion++;const nextRecovery=authRandom(12).toUpperCase().match(/.{1,4}/g).join('-');u.recoverySalt=authRandom();u.recoveryHash=await authHash(authNormalizeRecovery(nextRecovery),u.recoverySalt);if(authSessions[role]?.userId===u.id)delete authSessions[role];authSaveDatabase();authSaveSessions();authAudit('Recovered account and revoked old sessions',u);return {ok:true,recovery:nextRecovery};}
async function authResetForm(role){$('auth-status').textContent='Checking recovery code…';const r=await authResetValues(role,$('auth-email').value,$('auth-recovery').value,$('auth-password').value,$('auth-confirm').value);['auth-password','auth-confirm','auth-recovery'].forEach(id=>$(id).value='');if(!r.ok){$('auth-status').textContent=r.message;return;}authOneTimeRecovery=r.recovery;openModal('Password reset',`<p>Old sessions have been revoked. Save your replacement recovery code:</p><code class="auth-recovery-code">${esc(r.recovery)}</code>${button('Return to sign in',`$('modal').close();go('${AUTH_ROUTES[role].login}')`)}`);}
function authFillDemo(role,kind='default'){const demo=AUTH_DEMOS.find(d=>d.role===role&&(kind==='reviewer'?d.id==='REVIEWER-DEMO':kind==='delivery'?d.id==='DELIVERY-DEMO':d.id===({customer:'CUSTOMER-DEMO',worker:'WORKER-DEMO',admin:'ADMIN-DEMO'})[role]));$('auth-email').value=demo.email;$('auth-password').value=demo.password;toast('Demo details filled. Click Sign in.');}
function authPasswordField(id,label,autocomplete='current-password'){return `<label for="${id}">${label}</label><div class="auth-password-field"><input id="${id}" type="password" required minlength="10" autocomplete="${autocomplete}"><button type="button" class="ghost" onclick="authTogglePassword('${id}',this)" aria-label="Show ${label.toLowerCase()}">Show</button></div>`;}
function authTogglePassword(id,button){const visible=$(id).type==='password';$(id).type=visible?'text':'password';button.textContent=visible?'Hide':'Show';button.setAttribute('aria-label',(visible?'Hide ':'Show ')+'password');}
function authAccessPage(role,mode='login'){const r=AUTH_ROUTES[role],label=role==='admin'?'Admin':role==='worker'?'Worker':'Customer',user=authSession(role);const title=mode==='signup'?(role==='worker'?'Apply for a worker account':role==='admin'?'Accept your admin invitation':'Create your customer account'):mode==='reset'?'Recover your '+role+' account':'Sign in to '+label;let body='';if(mode==='login')body=`<form onsubmit="event.preventDefault();authLoginForm('${role}')">${field('auth-email','Email address','','email','required autocomplete="username"')}${authPasswordField('auth-password','Password')}<div class="auth-form-links">${link(r.reset,'Forgot password?')}</div><button type="submit" class="auth-submit">Sign in</button><p id="auth-status" role="status" class="form-error"></p></form><p class="auth-alternate">${role==='admin'?'Have an invitation?':'New here?'} ${link(r.signup,role==='worker'?'Request staff access':role==='admin'?'Register with invitation':'Create an account')}</p><details class="auth-demo"><summary>Use a sample account</summary><div class="actions">${button(role==='worker'?'Catalog worker · needs approval':'Fill demo details',`authFillDemo('${role}')`,'secondary')}${role==='worker'?button('Delivery worker',"authFillDemo('worker','delivery')",'secondary'):''}${role==='admin'?button('Independent reviewer',"authFillDemo('admin','reviewer')",'secondary'):''}</div></details>`;
if(mode==='signup')body=`<form onsubmit="event.preventDefault();authSignupForm('${role}')">${field('auth-name','Display name','','text','required autocomplete="name"')}${field('auth-email','Email address','','email','required autocomplete="email"')}${role==='worker'?select('auth-request-role','Requested role',['Catalog','Procurement','Delivery','Fieldworker'],'Catalog'):''}${role==='admin'?field('auth-invite','Invitation code','','text','required autocomplete="off"'):''}${authPasswordField('auth-password','Create password','new-password')}${authPasswordField('auth-confirm','Confirm password','new-password')}<small>At least 10 characters, uppercase, lowercase and a number.</small>${role==='worker'?note('Signup does not activate staff access. An admin must approve the worker and assign a role.'):role==='admin'?note('Public admin registration is disabled. Invitations are tied to a specific email.'):''}<button type="submit" class="auth-submit">${role==='worker'?'Request staff account':'Create account'}</button><p id="auth-status" role="status" class="form-error"></p></form><p>${link(r.login,'Already registered? Sign in →')}</p>`;
if(mode==='reset')body=`<form onsubmit="event.preventDefault();authResetForm('${role}')">${field('auth-email','Account email','','email','required')}${field('auth-recovery','Your local recovery code','','text','required autocomplete="off"')}${authPasswordField('auth-password','New password','new-password')}${authPasswordField('auth-confirm','Confirm new password','new-password')}${note('This local prototype uses the recovery code provided at signup. No email or SMS is sent.')}<button type="submit" class="auth-submit">Reset password</button><p id="auth-status" role="status" class="form-error"></p></form>${link(r.login,'Return to sign in →')}`;
return `<div class="auth-layout"><section class="auth-story"><div class="eyebrow">${label.toUpperCase()} APPLICATION</div><h1>${role==='customer'?'Your finds.<br>Your account.':role==='worker'?'Your role.<br>Your assigned work.':'Your team.<br>Your control center.'}</h1><p>${role==='customer'?'Keep your cart, quotations, addresses and orders in your own customer workspace.':role==='worker'?'Access assigned tasks and submit product updates after staff approval.':'Manage catalog approvals, business operations and team access with a separate admin identity.'}</p><div class="auth-role-pills"><span>Separate application sessions</span><span>Account-specific passwords</span><span>Shared approved catalog</span></div></section><section class="auth-form-panel"><div class="eyebrow">CHINALOWCOST · ${label.toUpperCase()}</div><h2>${title}</h2>${user?note('Currently signed in as '+esc(user.name)+'. '+link(authScopeHome(role),'Continue to your workspace →')):''}${body}<p class="auth-local-note">Local prototype accounts only. Use fictional emails and demo passwords. Production security requires a backend identity service.</p></section></div>`;}
function authPublicShell(content,page){const role=authRoleForPage(page);return `<header class="auth-header">${link('C02','<span class="brandmark">c</span>china<b>lowcost</b>.','brand')}<nav aria-label="Application sign-in">${['customer','worker','admin'].map(r=>link(AUTH_ROUTES[r].login,r[0].toUpperCase()+r.slice(1),r===role?'active-link':'')).join('')}</nav></header><main id="content" class="customer-main"><div class="back-row">${button('← Back','goBack()','secondary')}</div>${content}<div class="screen-meta">${page.ID} · ${esc(page.Screen)}</div></main>`;}
function authSecurityPage(role){const u=authSession(role);if(!u)return authAccessPage(role);return heading('Your '+role+' account & security','Password and session controls apply to this account only.',button('Sign out',`authLogout('${role}')`,'secondary'))+`<div class="split">${card('Account details',row('Name',esc(u.name))+row('Email',esc(u.email))+row('Application',esc(role))+row('Role / scope',esc(u.scope))+row('Session','Up to 8 hours · this browser tab')+note('Switching applications requires that application’s own login. Other application sessions remain separate.'))}${primaryForm('Change password',authPasswordField('auth-current','Current password')+authPasswordField('auth-new','New password','new-password')+authPasswordField('auth-confirm','Confirm new password','new-password')+'<p id="auth-status" role="status" class="form-error"></p>',`authPasswordForm('${role}')`,'Change password')}</div>`+(role==='admin'&&u.scope==='Manager'?authInvitationPanel():'');}
function authInvitationPanel(){return primaryForm('Invite another admin',field('auth-invite-email','Invited sample email','','email','required')+select('auth-invite-scope','Admin scope',['Catalog reviewer','Manager'],'Catalog reviewer')+note('A Manager creates a single-use invitation for a specific email. No email is sent from this prototype.'),"authCreateInvitation()",'Create local invitation')+card('Invitation records',table(['Email','Scope','Expiry','Status'],authDatabase.invitations.map(i=>[esc(i.email),esc(i.scope),new Date(i.expiresAt).toLocaleDateString('en-GB'),badge(i.used?'Used':i.expiresAt<Date.now()?'Expired':'Available','gray')])));}
function authCreateInvitation(){const u=authSession('admin');if(u?.scope!=='Manager'){toast('A Manager admin is required.');return;}const email=$('auth-invite-email').value.trim().toLowerCase();const invitation={code:'CLC-'+authRandom(8).toUpperCase(),email,scope:$('auth-invite-scope').value,expiresAt:Date.now()+7*86400000,used:false,issuer:u.id};authDatabase.invitations.push(invitation);authSaveDatabase();authAudit('Created admin invitation for '+email,u);openModal('Local admin invitation',row('Invited email',esc(email))+row('Scope',esc(invitation.scope))+`<code class="auth-recovery-code">${esc(invitation.code)}</code><p>No invitation was sent. Use this code on the Admin invitation signup page.</p>${link('A39','Open invitation signup','button secondary')}`);}
const authRequireBase=opsRequire;
opsRequire=(cap,admin=false)=>{const role=admin?'admin':'worker',u=authSession(role);if(!u){toast('Sign in to the '+role+' application with an approved account.');go(AUTH_ROUTES[role].login);return false;}if(admin&&!authCanPage(u,route)){toast('Your admin scope does not allow this action.');return false;}if(!admin)state.ops.workerId=u.workerId;return authRequireBase(cap,admin);};
const authNewDraftBase=opsNewDraft;
opsNewDraft=(sku,admin=false)=>{if(!opsRequire('catalog',admin))return;authNewDraftBase(sku,admin);const d=opsDraft(),u=authSession(admin?'admin':'worker');if(d&&u){d.requestedByUserId=u.id;d.owner=u.name+' · '+u.id;persist();}};
const authSaveDraftBase=opsSaveCatalog;
opsSaveCatalog=(admin=false,submit=false)=>{const u=authSession(admin?'admin':'worker');if(!u){toast('Sign in before saving a catalog draft.');return;}const d=opsDraft();if(d&&!admin&&d.staffId!==u.workerId){toast('This draft belongs to another worker.');return;}if(d){d.requestedByUserId=u.id;d.owner=u.name+' · '+u.id;}authSaveDraftBase(admin,submit);};
const authReviewBase=opsReviewCatalog;
opsReviewCatalog=(id,approve)=>{const u=authSession('admin'),d=state.ops.drafts.find(d=>d.id===id);if(!u||!d){toast('Sign in to an authorized admin account first.');return;}if(d.requestedByUserId===u.id){toast('Self-approval blocked. Another admin account must review this version.');return;}state.ops.reviewer=u.scope;authReviewBase(id,approve);};
const authStaffStatusBase=opsStaffStatus;
opsStaffStatus=(id,status)=>{const u=authSession('admin');if(u?.scope!=='Manager'){toast('A signed-in Manager account must approve or suspend workers.');return;}state.staffActor='Manager';authStaffStatusBase(id,status);authDatabase.users.filter(account=>account.workerId===id).forEach(account=>{account.accessStatus=status;if(status!=='Active')account.passwordVersion++;});if(status!=='Active'&&authDatabase.users.some(account=>account.workerId===id&&account.id===authSessions.worker?.userId)){delete authSessions.worker;authSaveSessions();}authSaveDatabase();authAudit('Staff status '+id+' → '+status,u);};
const authOpenTaskBase=opsOpenTask;
opsOpenTask=id=>{const task=state.ops.tasks.find(t=>t.id===id);if(!task)return;if(route.startsWith('A')&&authSession('admin')){openModal('Task '+task.id,row('Type',esc(task.type))+row('Assigned worker',esc(state.ops.staff.find(w=>w.id===task.staffId)?.name))+row('Location',esc(task.town+', '+task.region))+row('Status',badge(task.status))+link('A06','Manage assignments','button secondary'));return;}const u=authSession('worker');if(!u||task.staffId!==u.workerId){toast('This task is not assigned to your signed-in worker account.');return;}authOpenTaskBase(id);};
const authAddCartBase=addCart,authCreateQuoteBase=createQuote;
function authRequireCustomer(target){const u=authSession('customer');if(u){authSwitchRoom(u.id);return true;}authPendingSelection={sku:state.selected,qty:state.qty,mode:state.mode};authReturnTo.customer=target;go('C01');toast('Sign in to your customer account to save this item.');return false;}
addCart=(qty,wholesale=false)=>{if(authRequireCustomer('C07'))authAddCartBase(qty,wholesale);};
createQuote=()=>{if(authRequireCustomer('C08'))authCreateQuoteBase();};
customerPage=id=>{if(id==='C01')return authAccessPage('customer');if(id==='C23')return authAccessPage('customer','signup');if(id==='C24')return authAccessPage('customer','reset');if(id==='C25')return authSecurityPage('customer');return authCustomerBase(id)+(id==='C20'?card('Account security',links([['C25','Change password & sign out']])):'');};
