async function authProvisionWorker({name,email,password,confirm,requestedRole}){
 const manager=authSession('admin');if(manager?.scope!=='Manager')return {ok:false,message:'A signed-in Manager is required.'};
 email=email.trim().toLowerCase();if(!name.trim()||!/^\S+@\S+\.\S+$/.test(email))return {ok:false,message:'Enter a worker name and valid email.'};
 const error=authPasswordError(password);if(error||password!==confirm)return {ok:false,message:error||'Passwords do not match.'};
 if(authUser('worker',email))return {ok:false,message:'This email already has a worker account.'};
 if(!['Catalog','Procurement','Delivery','Fieldworker'].includes(requestedRole))return {ok:false,message:'Choose a valid worker role.'};
 const workerId='ST-'+authRandom(6),recovery=authRandom(12).toUpperCase().match(/.{1,4}/g).join('-');
 const user=await authBuildUser({id:'WORKER-'+authRandom(8),role:'worker',name:name.trim(),email,workerId,scope:requestedRole,accessStatus:'Active'},password,recovery);
 state.ops.staff.push({id:workerId,name:user.name,role:requestedRole,team:'Pending assignment',status:'Active',region:'Lagos',town:'Ikeja',shift:false,lastSeen:null});
 authDatabase.users.push(user);authSaveDatabase();authAudit('Created worker login '+email,manager);return {ok:true,user,recovery};
}
async function authProvisionWorkerForm(){
 const result=await authProvisionWorker({name:$('staff-account-name').value,email:$('staff-account-email').value,password:$('staff-account-password').value,confirm:$('staff-account-confirm').value,requestedRole:$('staff-account-role').value});
 $('staff-account-password').value='';$('staff-account-confirm').value='';if(!result.ok){$('staff-account-status').textContent=result.message;return;}
 openModal('Worker login created',row('Worker',esc(result.user.name))+row('Login email',esc(result.user.email))+row('Role',esc(result.user.scope))+'<p>Give the worker their login email and the password you chose. They can change their password after signing in. Save and share this recovery code privately:</p><code class="auth-recovery-code">'+esc(result.recovery)+'</code><p>The password is not displayed or stored as readable text.</p>');
}
function authRemoveWorkerAccess(id){const manager=authSession('admin');if(manager?.scope!=='Manager'){toast('A Manager is required.');return;}const user=authDatabase.users.find(u=>u.id===id&&u.role==='worker');if(!user)return;opsStaffStatus(user.workerId,'Suspended');user.accessStatus='Removed';authSaveDatabase();authAudit('Removed worker login access '+user.email,manager);render();toast('Worker access removed. Existing sessions are revoked.');}
function authWorkerAccountsPanel(){if(authSession('admin')?.scope!=='Manager')return '';return primaryForm('Create worker login',field('staff-account-name','Worker name','','text','required')+field('staff-account-email','Worker login email','','email','required')+select('staff-account-role','Worker role',['Catalog','Procurement','Delivery','Fieldworker'],'Catalog')+authPasswordField('staff-account-password','Initial password','new-password')+authPasswordField('staff-account-confirm','Confirm initial password','new-password')+'<p>Give these login details directly to the worker. Only an admin can create staff access.</p><p id="staff-account-status" role="status" class="form-error"></p>','authProvisionWorkerForm()','Create worker login')+card('Worker login access',table(['Worker','Email','Role','Access','Action'],authDatabase.users.filter(u=>u.role==='worker').map(u=>{const staff=state.ops.staff.find(w=>w.id===u.workerId);return [esc(u.name),esc(u.email),esc(u.scope),badge(u.accessStatus==='Removed'?'Removed':staff?.status||'Unavailable'),u.accessStatus==='Removed'?button('Restore access',"opsStaffStatus('"+u.workerId+"','Active')",'secondary'):button('Remove access',"authRemoveWorkerAccess('"+u.id+"')",'danger')];})))+note('Removing access revokes the worker session and blocks login while keeping their task and audit history. Restore access only when authorized.');}
const authAdminManagedStaff=adminPage;
