/* Unified, account-scoped staff job workflow (local prototype). */
const JOB_TYPES=['Supplier visit','Product photos / video','Catalog entry','Supplier pickup','Inspection','Packing','Delivery','Return collection'];
const JOB_ROLES={Catalog:['Supplier visit','Product photos / video','Catalog entry'],Procurement:['Supplier pickup','Inspection','Packing'],Delivery:['Delivery','Return collection'],Fieldworker:JOB_TYPES};
function jobsInit(){opsInit();state.ops.tasks.forEach(t=>{t.revision=t.revision||1;t.history=t.history||[];t.submissions=t.submissions||[];if(t.status==='Completed'&&!t.reviewedBy){t.status='Needs correction';t.legacyEvidence=true;t.reviewNote='Earlier completion has no independent approval. Resume and submit fresh evidence.';}});}
function jobsManager(){const u=authSession('admin');return route.startsWith('A')&&u?.scope==='Manager'?u:null;}
function jobsActor(t){const u=authSession('worker');const w=state.ops.staff.find(w=>w.id===u?.workerId);return route.startsWith('W')&&u&&w?.status==='Active'&&t.staffId===w.id&&(JOB_ROLES[w.role]||[]).includes(t.type)?u:null;}
function jobsRecord(t,action,actor,details=''){t.revision++;t.history.unshift({at:Date.now(),action,actor:actor.id,name:actor.name,details,revision:t.revision});authAudit(action+' · '+t.id+(details?' · '+details:''),actor);}
function jobsFail(message){toast(message);return {ok:false,message};}
function jobsTransition(id,action,{revision,note='',evidence='',staffId,units}={}){
 jobsInit();const t=state.ops.tasks.find(t=>t.id===id);if(!t)return jobsFail('Task not found.');if(revision!==undefined&&revision!==t.revision)return jobsFail('This job changed. Reopen it before acting.');
 const worker=jobsActor(t),manager=jobsManager();const terminal=['Completed','Revoked'].includes(t.status);
 if(['accept','start','submit','issue'].includes(action)&&(!worker||terminal))return jobsFail('Only the active assigned worker can update an open job.');
 if(['approve','correction','revoke','reassign'].includes(action)&&!manager)return jobsFail('A signed-in Manager is required.');
 if(action==='accept'){if(t.status!=='Assigned')return jobsFail('Only an assigned job can be accepted.');t.status='Accepted';jobsRecord(t,'Accepted',worker);}
 else if(action==='start'){if(!['Accepted','Needs correction','Blocked'].includes(t.status))return jobsFail('Accept the job before starting it.');t.status='In progress';t.startedAt=Date.now();jobsRecord(t,'Started',worker);}
 else if(action==='issue'){if(!['Accepted','In progress','Needs correction'].includes(t.status)||!note.trim())return jobsFail('Enter the issue for an accepted or active job.');t.status='Blocked';t.issue=note.trim();jobsRecord(t,'Reported issue',worker,note.trim());}
 else if(action==='submit'){
 if(t.status!=='In progress')return jobsFail('Start the job before submitting work.');if(note.trim().length<10||!evidence.trim()||!Number.isInteger(Number(units))||Number(units)<1||Number(units)>t.qty)return jobsFail('Provide a work summary (10+ characters), evidence reference and valid completed units.');
 if(t.type==='Supplier pickup'&&!state.ops.receipts.some(r=>r.taskId===id))return jobsFail('Record the assigned goods receipt before submitting pickup work.');
 if(t.type==='Delivery'&&!t.deliveryVerified)return jobsFail('Verify dispatched delivery with the customer code before submission.');
 if(t.type==='Catalog entry'&&!state.ops.drafts.some(d=>d.staffId===t.staffId&&d.sku===t.sku&&['Pending review','Published','Approved'].includes(d.status)))return jobsFail('Submit a matching product draft for independent catalog review first.');
 const submission={id:'SUB-'+authRandom(8),workerId:worker.id,staffId:t.staffId,at:Date.now(),summary:note.trim(),evidence:evidence.trim(),units:Number(units),assignmentRevision:t.revision};t.submissions.unshift(submission);t.status='Submitted for review';t.submittedAt=submission.at;delete t.reviewedBy;jobsRecord(t,'Submitted for review',worker,submission.summary);
 }
 else if(action==='approve'||action==='correction'){
 if(t.status!=='Submitted for review')return jobsFail('Only submitted work can be reviewed.');if(action==='approve'&&t.type==='Packing'&&!state.ops.receipts.some(r=>r.sku===t.sku&&r.accepted>=t.qty&&state.ops.tasks.some(p=>p.id===r.taskId&&p.status==='Completed'&&p.reviewedBy)) )return jobsFail('Approve received goods before authorizing packing dispatch.');const sub=t.submissions[0];if(!sub)return jobsFail('A worker must submit fresh evidence before review.');if(sub.workerId===manager.id)return jobsFail('Independent review is required.');if(action==='correction'&&!note.trim())return jobsFail('Explain what the worker must correct.');
 t.status=action==='approve'?'Completed':'Needs correction';t.reviewNote=note.trim();t.reviewedBy=manager.id;t.reviewedAt=Date.now();sub.review={action,by:manager.id,at:t.reviewedAt,note:t.reviewNote};if(action==='approve'){t.completedAt=Date.now();if(t.type==='Delivery')state.delivery=true;if(t.type==='Packing')state.dispatch=true;if(t.type==='Supplier pickup'){const receipt=state.ops.receipts.find(r=>r.taskId===t.id);state.pickup=state.pickup||receipt?.accepted>0;state.inspection=state.inspection||receipt?.accepted>0;}if(t.type==='Return collection')state.returnCollected=true;}jobsRecord(t,action==='approve'?'Approved completion':'Requested correction',manager,note.trim());
 }
 else if(action==='revoke'){if(terminal)return jobsFail('This job is already closed.');if(!note.trim())return jobsFail('Give a reason for revocation.');t.status='Revoked';t.revokedAt=Date.now();jobsRecord(t,'Revoked assignment',manager,note.trim());}
 else if(action==='reassign'){
 if(terminal)return jobsFail('Create a follow-up job for closed work.');const w=state.ops.staff.find(w=>w.id===staffId&&w.status==='Active');if(!w||!(JOB_ROLES[w.role]||[]).includes(t.type)||staffId===t.staffId||!note.trim())return jobsFail('Choose another active worker with the correct role and give a reason.');const old=t.staffId;t.staffId=staffId;t.status='Assigned';delete t.deliveryVerified;delete t.reviewedBy;jobsRecord(t,'Reassigned',manager,old+' → '+staffId+' · '+note.trim());
 }else return jobsFail('Unknown action.');persist();return {ok:true};
}
function jobsAction(id,action,revision){const r=jobsTransition(id,action,{revision,note:$('job-note')?.value||'',evidence:$('job-evidence')?.value||'',units:$('job-units')?.value,staffId:$('job-reassign')?.value});if(r.ok){$('modal').close();render();toast('Job updated.');}}
function jobsOpen(id){jobsInit();const t=state.ops.tasks.find(t=>t.id===id);if(!t)return;const manager=route.startsWith('A')?jobsManager():null,worker=route.startsWith('W')?jobsActor(t):null;if(!manager&&!worker){toast('This job is outside your account access.');return;}state.ops.selectedTask=id;persist();const action=(text,a,cls='secondary')=>button(text,"jobsAction('"+id+"','"+a+"',"+t.revision+")",cls);let controls='';
 if(worker){if(t.status==='Assigned')controls+=action('Accept job','accept');if(['Accepted','Needs correction','Blocked'].includes(t.status))controls+=action('Start / resume work','start');if(t.status==='In progress')controls+=action('Submit for admin review','submit','');if(['Accepted','In progress','Needs correction'].includes(t.status))controls+=action('Report issue','issue');const target=opsTaskRoute(t.type);if(!['Revoked','Completed'].includes(t.status))controls+=link(target,'Open work tools','button secondary');}
 if(manager&&!['Revoked','Completed'].includes(t.status)){if(t.status==='Submitted for review')controls+=action('Approve completion','approve','')+action('Return for correction','correction');controls+=select('job-reassign','Reassign to worker',state.ops.staff.filter(w=>w.id!==t.staffId&&w.status==='Active'&&(JOB_ROLES[w.role]||[]).includes(t.type)).map(w=>w.id),'')+action('Reassign job','reassign')+action('Revoke job','revoke','danger');}
 openModal(t.id+' · '+t.type,row('Assigned worker',esc(state.ops.staff.find(w=>w.id===t.staffId)?.name||'Unassigned'))+row('Status',badge(t.status))+row('Reference / SKU',esc(t.reference+' / '+t.sku))+row('Location',esc(t.town+', '+t.region))+row('Due',new Date(t.due).toLocaleString('en-GB'))+(t.reviewNote?note('Review feedback: '+esc(t.reviewNote),'warn'):'')+field('job-note',manager?'Review / reassignment / revocation reason':'Work summary / issue','','text')+(worker?field('job-evidence','Evidence reference (receipt, media or report ID)','','text')+field('job-units','Completed units',t.qty,'number','min="1" max="'+t.qty+'"'):'')+'<div class="actions">'+controls+'</div>'+card('Submitted evidence',t.submissions.map(s=>row(opsTime(s.at),esc(s.summary)+'<small>'+esc(s.evidence)+' · '+s.units+' units · '+esc(s.review?.action||'Awaiting review')+'</small>')).join('')||note('No evidence submitted.'))+card('Job history',t.history.map(e=>row(esc(e.action),esc(e.name+' · '+e.details)+'<small>'+opsTime(e.at)+'</small>')).join('')||note('Initial assignment')));
}
opsOpenTask=jobsOpen;
opsStartTask=id=>{const t=state.ops.tasks.find(t=>t.id===id);const r=jobsTransition(id,'start',{revision:t?.revision});if(r.ok)render();};
opsBlockTask=id=>jobsOpen(id);
opsCurrentTask=type=>{jobsInit();const active=state.ops.tasks.filter(t=>t.type===type&&t.staffId===authSession('worker')?.workerId&&!['Revoked','Completed','Submitted for review'].includes(t.status));return active.find(t=>t.id===state.ops.selectedTask)||active[0];};
opsTaskCard=t=>t?card('Assignment '+t.id,row('Status',badge(t.status))+row('Location',esc(t.town+', '+t.region))+button('Manage job / submit evidence',"jobsOpen('"+t.id+"')",'secondary')):note('No open assigned job.');
const jobsReceiveBase=opsReceive,jobsDeliveryBase=opsConfirmDelivery;
opsReceive=id=>{const t=state.ops.tasks.find(t=>t.id===id);if(!t||!jobsActor(t)||t.status!=='In progress'){toast('Start your assigned pickup job first.');return;}const priorPickup=state.pickup,priorInspection=state.inspection;jobsReceiveBase(id);state.pickup=priorPickup;state.inspection=priorInspection;if(state.ops.receipts.some(r=>r.taskId===id)){t.status='In progress';t.receiptRecorded=true;persist();render();}};
opsConfirmDelivery=()=>{const t=opsCurrentTask('Delivery');if(!t||!jobsActor(t)||t.status!=='In progress'){toast('Start your assigned delivery first.');return;}const valid=state.dispatch&&$('ops-delivery-otp').value==='123456';jobsDeliveryBase();if(valid){t.status='In progress';t.deliveryVerified=true;state.delivery=false;persist();render();toast('Delivery evidence verified. Submit the job for admin review.');}};
const jobsRenderBase=render;
render=()=>{if(authBooted)jobsInit();jobsRenderBase();};
const jobsPageAdmin=adminPage,jobsPageWorker=workerPage;
workerPage=id=>{let html=jobsPageWorker(id);if(id==='W10')html=heading('Packing & dispatch approval','Submit packing evidence through your assigned job. Manager approval records dispatch.')+state.ops.tasks.filter(t=>t.type==='Packing'&&t.staffId===authSession('worker')?.workerId).map(t=>opsTaskCard(t)).join('');if(id==='W14')html=heading('Return collection','Record evidence in the assigned job; admin approval confirms completion.')+state.ops.tasks.filter(t=>t.type==='Return collection'&&t.staffId===authSession('worker')?.workerId).map(t=>opsTaskCard(t)).join('');return html;};
adminPage=id=>jobsPageAdmin(id)+(id==='A26'&&jobsManager()?card('Work awaiting approval',table(['Task','Reference','Location','Worker','Status',''],opsTaskRows(state.ops.tasks.filter(t=>t.status==='Submitted for review')))):'');
opsTaskRoute=type=>({'Supplier visit':'W03','Product photos / video':'W04','Catalog entry':'W06','Supplier pickup':'W08','Inspection':'W09','Packing':'W10','Delivery':'W11','Return collection':'W14'}[type]||'W02');
const jobsRequireBase=opsRequire;
opsRequire=(cap,admin=false)=>{if(!jobsRequireBase(cap,admin))return false;if(admin)return true;const types={catalog:['Supplier visit','Product photos / video','Catalog entry'],visit:['Supplier visit'],procurement:['Supplier pickup','Inspection','Packing'],delivery:['Delivery','Return collection']}[cap];if(types&&!state.ops.tasks.some(t=>t.staffId===authSession('worker')?.workerId&&types.includes(t.type)&&t.status==='In progress')){toast('An in-progress assigned job is required for this work.');return false;}return true;};
const jobsAssignmentBase=opsAssignmentPage;
opsAssignmentPage=()=>jobsAssignmentBase().replace(/(<select id="ops-task-type">)[\s\S]*?(<\/select>)/,(_,open,close)=>open+JOB_TYPES.map(x=>'<option>'+x+'</option>').join('')+close)+note('Open any job to reassign, revoke, review evidence, approve completion or request corrections. Completed means approved by a Manager.');
opsAssignTask=()=>{jobsInit();const u=jobsManager();if(!u){toast('A Manager must assign work.');return;}const w=state.ops.staff.find(w=>w.name===$('ops-task-worker').value&&w.status==='Active'),type=$('ops-task-type').value,qty=Number($('ops-task-qty').value),hours=Number($('ops-task-hours').value);if(!w||!(JOB_ROLES[w.role]||[]).includes(type)||!Number.isInteger(qty)||qty<1||qty>100000||!Number.isFinite(hours)||hours<1||hours>168||!$('ops-task-ref').value.trim()||!$('ops-task-town').value.trim()||!NG_TOWNS[$('ops-task-region').value]||!products.some(p=>p.id===$('ops-task-sku').value)){toast('Check worker role, product, quantity, destination, reference and deadline.');return;}const t={id:'TASK-'+authRandom(8),type,staffId:w.id,reference:$('ops-task-ref').value.trim(),sku:$('ops-task-sku').value,qty,region:$('ops-task-region').value,town:$('ops-task-town').value.trim(),status:'Assigned',due:Date.now()+hours*3600000,revision:1,history:[],submissions:[]};state.ops.tasks.push(t);jobsRecord(t,'Assigned',u,w.name);render();};
const jobsSyncOrderBase=opsSyncOrder;
