/* WhatsApp click-to-chat configuration; dummy mode never creates an external link. */
const WA_DUMMY='2340000000000';
function waSettings(){if(!state.whatsapp)state.whatsapp={number:WA_DUMMY,mode:'Demo preview',enabled:true};return state.whatsapp;}
function waNormalize(number){return String(number).trim().replace(/[+\s()-]/g,'');}
function waValid(number){return /^[1-9][0-9]{7,14}$/.test(number)&&number!==WA_DUMMY&&!/^2340/.test(number);}
function waSaveValues({number,mode,enabled}){const user=authSession('admin');if(!route.startsWith('A')||user?.scope!=='Manager')return {ok:false,message:'A Manager must configure WhatsApp.'};number=waNormalize(number);if(!['Demo preview','Live chat link'].includes(mode))return {ok:false,message:'Choose a valid mode.'};if(mode==='Live chat link'&&!waValid(number))return {ok:false,message:'Enter an actual international business number before enabling live links.'};if(mode==='Demo preview'&&number!==WA_DUMMY&&!waValid(number))return {ok:false,message:'Use the dummy number or a valid international number.'};state.whatsapp={number,mode,enabled:!!enabled};authAudit('Updated WhatsApp click-to-chat configuration · '+mode,user);return {ok:true};}
function waSaveForm(){const r=waSaveValues({number:$('wa-number').value,mode:$('wa-mode').value,enabled:$('wa-enabled').checked});$('wa-status').textContent=r.ok?'WhatsApp settings saved.':r.message;}
function waMessage(kind='support'){if(kind==='product'){const p=picked();return 'Hello ChinaLowCost, I am interested in '+p.name+' (SKU: '+p.id+'). Quantity: '+state.qty+'. Please confirm availability, price and transportation options.';}if(kind==='order')return 'Hello ChinaLowCost, I need help with my order. I will provide my order reference in this chat.';return 'Hello ChinaLowCost, I would like assistance with your products or an order.';}
function waChatData(kind='support'){const cfg=waSettings(),message=waMessage(kind);return {number:cfg.number,message,url:cfg.enabled&&cfg.mode==='Live chat link'&&waValid(cfg.number)?'https://wa.me/'+cfg.number+'?text='+encodeURIComponent(message):null,enabled:cfg.enabled};}
function waOpen(kind='support'){const data=waChatData(kind);if(!data.enabled){toast('WhatsApp contact is currently disabled. Use in-app support.');return;}openModal(data.url?'Continue to WhatsApp':'WhatsApp · demo preview',row('Business number','+'+esc(data.number))+'<label for="wa-preview-message">Prepared message</label><textarea id="wa-preview-message" rows="5" readonly>'+esc(data.message)+'</textarea>'+note(data.url?'WhatsApp will open with this draft. Review it there and choose whether to send.':'Dummy configuration: no WhatsApp conversation will be opened and no message will be sent.')+(data.url?'<a class="button" href="'+esc(data.url)+'" target="_blank" rel="noopener noreferrer">Open WhatsApp</a>':'')+button('Close',"$('modal').close()",'secondary'));}
function waContactPanel(kind='support'){const cfg=waSettings();return card(kind==='product'?'Ask about this product on WhatsApp':'Contact ChinaLowCost on WhatsApp',note(cfg.mode==='Demo preview'?'Demo preview · dummy business number.':'Opens a prepared chat with our business. You choose whether to send.')+button(kind==='product'?'Ask about this product':'Chat with support',"waOpen('"+kind+"')",'secondary',!cfg.enabled));}
function waConfigPanel(){const cfg=waSettings(),user=authSession('admin');if(user?.scope!=='Manager')return note('A Manager configures the business WhatsApp number.');return primaryForm('WhatsApp business number',field('wa-number','International number',cfg.number,'tel','required autocomplete="off"')+select('wa-mode','Connection mode',['Demo preview','Live chat link'],cfg.mode)+'<label class="check"><input id="wa-enabled" type="checkbox" '+(cfg.enabled?'checked':'')+'> Show customer WhatsApp buttons</label>'+note('Default dummy number: +234 000 000 0000. Keep Demo preview while testing. Replace it with your business number, including country code, and select Live chat link when ready. No API key is needed for a chat link.')+'<p id="wa-status" role="status"></p>','waSaveForm()','Save WhatsApp settings')+card('Test customer handoff',button('Preview support message',"waOpen('support')",'secondary')+note('This configures click-to-chat only. Automated messages, a synchronized inbox, templates and delivery callbacks need the WhatsApp Business Platform and a secure backend.'));}
const waCustomerBase=customerPage,waAdminBase=adminPage;
const waNavBase=navLabel;navLabel=p=>p.ID==='A23'?'WhatsApp settings':waNavBase(p);
customerPage=id=>id==='C18'?heading('Customer support','Ask about products, quotations, delivery or returns.')+'<div class="split">'+chat('Customer support','support')+waContactPanel('support')+'</div>':waCustomerBase(id)+(['C07','C16'].includes(id)?waContactPanel(id==='C07'?'product':'order'):'');
adminPage=id=>id==='A23'?heading('WhatsApp settings','Configure the business contact number and preview customer messages.')+waConfigPanel():waAdminBase(id)+(id==='A30'?card('WhatsApp contact configuration',link('A23','Manage business number and demo / live chat mode','button secondary')):'');


/* Configuration-free operational improvements. */
