const ENH_CHECKS={'Supplier visit':['Supplier contact confirmed','Capture permission recorded','Visit report recorded'],'Product photos / video':['Media captured','Product labels visible','Usage permission recorded'],'Catalog entry':['Specifications verified','MOQ and prices checked','Draft submitted for review'],'Supplier pickup':['Quantity checked','Receipt recorded','Discrepancies noted'],'Inspection':['Condition checked','Quantities reconciled','Inspection evidence recorded'],'Packing':['Goods matched to order','Packaging checked','Handover evidence recorded'],'Delivery':['Destination confirmed','Customer verification completed','Delivery evidence recorded'],'Return collection':['Returned units counted','Condition recorded','Collection evidence recorded']};
function enhChecklist(id,index,value){const t=state.ops.tasks.find(t=>t.id===id);if(!t||!jobsActor(t)||!['Accepted','In progress','Needs correction'].includes(t.status))return;t.checks=t.checks||{};t.checks[index]=!!value;persist();}
const enhJobsOpen=jobsOpen;jobsOpen=id=>{enhJobsOpen(id);const t=state.ops.tasks.find(t=>t.id===id);if(!t||(!jobsManager()&&!jobsActor(t)))return;const checks=ENH_CHECKS[t.type]||[];const disabled=!jobsActor(t)||!['Accepted','In progress','Needs correction'].includes(t.status);$('modal').innerHTML+=card('Work checklist',checks.map((text,i)=>'<label class="check"><input type="checkbox" '+(t.checks?.[i]?'checked ':'')+(disabled?'disabled ':'')+'onchange="enhChecklist(&quot;'+id+'&quot;,'+i+',this.checked)">'+esc(text)+'</label>').join(''))+row('Priority',esc(t.priority||'Normal'))+(t.due<Date.now()&&!['Completed','Revoked'].includes(t.status)?note('Overdue: ask the Manager for a revised plan.','warn'):'');};opsOpenTask=jobsOpen;
const enhTransition=jobsTransition;jobsTransition=(id,action,data={})=>{const t=state.ops.tasks.find(t=>t.id===id);if(action==='submit'&&t&&(ENH_CHECKS[t.type]||[]).some((_,i)=>!t.checks?.[i]))return jobsFail('Complete the job checklist before submitting.');const old=t?.staffId;const r=enhTransition(id,action,data);if(!r.ok)return r;const e=enhInit();if(action==='reassign')t.checks={};const worker=authDatabase.users.find(u=>u.workerId===t.staffId);if(worker)enhNotify(worker.id,t.id+': '+t.status,'W02');if(old&&old!==t.staffId){const prior=authDatabase.users.find(u=>u.workerId===old);if(prior)enhNotify(prior.id,t.id+': assignment removed','W02');}if(['submit','issue'].includes(action))authDatabase.users.filter(u=>u.role==='admin'&&u.scope==='Manager').forEach(u=>enhNotify(u.id,t.id+': '+t.status,'A26'));if(t.orderId&&e.orders[t.orderId]){const o=e.orders[t.orderId];o.shipment=o.shipment||{};if(action==='approve'&&t.type==='Packing')o.shipment.dispatched=true;if(action==='approve'&&t.type==='Delivery')o.shipment.delivered=true;}persist();return r;};
const enhAssign=opsAssignTask;opsAssignTask=()=>{const priority=$('enh-job-priority')?.value||'Normal',orderId=$('enh-job-order')?.value;const linked=enhInit().orders[orderId];if(linked&&['Supplier pickup','Inspection','Packing'].includes($('ops-task-type').value)&&!linked.snapshot.lines.some(l=>l.sku===$('ops-task-sku').value&&Number($('ops-task-qty').value)<=l.qty)){toast('Match the product and quantity to the selected order.');return;}const before=state.ops.tasks.length;enhAssign();if(state.ops.tasks.length>before){const t=state.ops.tasks.at(-1);t.priority=priority;const order=enhInit().orders[orderId];if(order){t.orderId=order.id;t.customerId=order.customerId;t.reference=order.id;}const u=authDatabase.users.find(u=>u.workerId===t.staffId);if(u)enhNotify(u.id,'New '+t.type+' job: '+t.id,'W02');persist();}};
const enhAssignmentPage=opsAssignmentPage;opsAssignmentPage=()=>enhAssignmentPage().replace('<form onsubmit="event.preventDefault();opsAssignTask()">','<form onsubmit="event.preventDefault();opsAssignTask()">'+select('enh-job-priority','Priority',['Normal','High','Urgent'],'Normal')+select('enh-job-order','Related order',['Unlinked job',...Object.keys(enhInit().orders)],enhInit().selectedOrderId||'Unlinked job'));
function enhArchiveOrder(){const u=authSession('customer');if(!u||!state.orderSnapshot)return null;const e=enhInit();let id=state.orderSnapshot.id;if(!id){id='CLC-'+new Date().toISOString().slice(0,10).replaceAll('-','')+'-'+authRandom(4).toUpperCase();state.orderSnapshot.id=id;}if(!e.orders[id])e.orders[id]={id,customerId:u.id,at:Date.now(),snapshot:authCopy(state.orderSnapshot),shipment:{dispatched:false,delivered:false}};persist();return e.orders[id];}
