function enhOrderList(){const u=authSession('customer'),orders=Object.values(enhInit().orders).filter(o=>o.customerId===u?.id);return heading('Your orders','Account-specific order history. Payments remain simulated.')+card('Orders',orders.map(o=>row(esc(o.id),money(o.snapshot.total)+' · '+(o.shipment?.delivered?'Delivered':o.shipment?.dispatched?'Dispatched':'Confirmed')+'<div class="actions">'+button('Reorder',"enhReorder('"+o.id+"')",'secondary')+button('Track',"enhTrack('"+o.id+"')",'ghost')+'</div>')).join('')||note('No orders placed with this account yet.'));}
