function enhReorder(id){const o=enhInit().orders[id];if(!o||o.customerId!==authSession('customer')?.id)return;const lines=o.snapshot.lines||[];if(!lines.length||lines.some(l=>!products.some(p=>p.id===l.sku&&!p.quoteOnly))){toast('Some products require a new quotation or are unavailable. Contact support.');return;}openModal('Reorder with current prices?',note('This replaces your current cart. Prices, discounts, MOQ, stock and transportation must be reviewed again.')+button('Replace cart',"enhConfirmReorder('"+id+"')")+button('Cancel',"$('modal').close()",'secondary'));}
