function enhSuppliersPanel(){return primaryForm('Add supplier record',field('enh-supplier-name','Trading name','','text','required maxlength="120"')+field('enh-supplier-contact','Business contact','','text','required maxlength="120"')+field('enh-supplier-town','Premises / town','','text','required maxlength="200"')+field('enh-supplier-agreement','Agreement / verification reference','','text','maxlength="120"'),'enhSupplierSave()','Save supplier')+card('Saved supplier records',table(['Supplier','Contact','Premises','Verification',''],enhInit().suppliers.map(s=>[esc(s.name),esc(s.contact),esc(s.town),badge(s.status),button(s.status==='Verified'?'Put on hold':'Mark verified',"enhSupplierStatus('"+s.id+"')",'secondary')])));}
