function enhRoomForPage(role,u){if(!u)return 'guest';const e=enhInit();if(role==='admin')return e.orders[e.selectedOrderId]?.customerId||'guest';const t=state.ops.tasks.find(t=>t.id===state.ops.selectedTask&&t.staffId===u.workerId);return t?.customerId||'guest';}
