const enhBoundTransition=jobsTransition;jobsTransition=(id,action,data={})=>{const t=state.ops.tasks.find(t=>t.id===id),o=t?.orderId&&enhInit().orders[t.orderId];if(o&&action==='approve'&&t.type==='Packing'&&!state.ops.receipts.some(r=>r.sku===t.sku&&r.accepted>=t.qty&&state.ops.tasks.some(p=>p.id===r.taskId&&p.orderId===t.orderId&&p.status==='Completed'&&p.reviewedBy)))return jobsFail('This order needs its own approved goods receipt before dispatch.');const r=enhBoundTransition(id,action,data);if(r.ok&&action==='approve'&&o){const current=state.orderSnapshot?.id;if(current!==o.id){state.dispatch=!!enhInit().orders[current]?.shipment?.dispatched;state.delivery=!!enhInit().orders[current]?.shipment?.delivered;}persist();}return r;};
