function enhParseCSV(text){if(text.length>500000)throw Error('Use a CSV under 500 KB.');const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++;}else if(!quoted&&cell.length)throw Error('Invalid CSV quoting.');else quoted=!quoted;}else if(!quoted&&(c===','||c==='\n')){row.push(cell.replace(/\r$/,''));cell='';if(c==='\n'){if(row.some(v=>v.trim()))rows.push(row);row=[];}}else cell+=c;}if(quoted)throw Error('Unclosed CSV quote.');row.push(cell.replace(/\r$/,''));if(row.some(v=>v.trim()))rows.push(row);return rows;}
let enhImportPreview=null;
function enhImportValidate(text){const rows=enhParseCSV(text),header=rows.shift()||[];const fields=['template_sku','sku','title','retail','bulk','volume','moq','pack','threshold'];if(header.join(',')!==fields.join(','))throw Error('Use the exact template header.');if(!rows.length||rows.length>200)throw Error('Import between 1 and 200 products.');const seen=new Set();return rows.map((r,i)=>{if(r.length!==fields.length)throw Error('Row '+(i+2)+': incorrect columns.');const d=Object.fromEntries(fields.map((k,j)=>[k,r[j].trim()]));const p=products.find(p=>p.id===d.template_sku);if(!p||!/^[A-Z0-9_-]{3,30}$/.test(d.sku)||!d.title||seen.has(d.sku)||products.some(p=>p.id===d.sku)||state.ops.drafts.some(x=>x.sku===d.sku))throw Error('Row '+(i+2)+': invalid template, duplicate SKU or missing title.');seen.add(d.sku);for(const k of fields.slice(3))d[k]=Number(d[k]);if(![d.retail,d.bulk,d.volume].every(n=>Number.isFinite(n)&&n>0)||d.retail<d.bulk||d.bulk<d.volume||![d.moq,d.pack,d.threshold].every(n=>Number.isInteger(n)&&n>0&&n<=100000)||d.moq%d.pack||d.threshold%d.pack||d.threshold<d.moq)throw Error('Row '+(i+2)+': invalid prices, MOQ or pack rules.');return d;});}
function enhImportPreviewForm(){if(!jobsManager())return;try{enhImportPreview=enhImportValidate($('enh-import-text').value);$('enh-import-status').textContent=enhImportPreview.length+' valid rows. Review the preview, then create drafts.';$('enh-import-preview').innerHTML=table(['SKU','Title','Retail','Wholesale','Volume'],enhImportPreview.map(r=>[esc(r.sku),esc(r.title),money(r.retail),money(r.bulk),money(r.volume)]));}catch(e){enhImportPreview=null;$('enh-import-status').textContent=e.message;$('enh-import-preview').innerHTML='';}}
async function enhImportFile(input){const f=input.files?.[0];if(!f)return;if(f.size>500000){$('enh-import-status').textContent='Use a file under 500 KB.';return;}$('enh-import-text').value=await f.text();enhImportPreview=null;$('enh-import-preview').innerHTML='';}
function enhImportCommit(){const u=jobsManager();if(!u||!enhImportPreview){toast('Validate a CSV first.');return;}let rows;try{rows=enhImportValidate($('enh-import-text').value);}catch(e){toast(e.message);return;}if(JSON.stringify(rows)!==JSON.stringify(enhImportPreview)){toast('CSV changed. Preview it again.');return;}for(const r of rows){const p=products.find(p=>p.id===r.template_sku);state.ops.drafts.push({id:'IMPORT-'+authRandom(8),sku:r.sku,title:r.title,category:p.category,subcategory:p.subcategory,style:p.style,quality:p.quality,condition:p.condition,variant:p.variant,moq:r.moq,pack:r.pack,threshold:r.threshold,retail:r.retail,bulk:r.bulk,volume:r.volume,cost:0,quoteOnly:!!p.quoteOnly,specs:{...p.specs},rights:false,rightsRef:'',owner:u.name+' · '+u.id,requestedByUserId:u.id,staffId:null,status:'Draft',version:1,art:p.art,actualKg:0,volumeKg:0,createdAt:Date.now()});}authAudit('Imported '+rows.length+' catalog drafts',u);enhImportPreview=null;render();toast('Drafts created. Verify specifications, costs, weights, images and permission before review.');}
function enhImportPanel(){if(!jobsManager())return '';return card('Bulk catalog import · CSV',note('Create up to 200 new draft SKUs using an existing product as a category template. Nothing is published. Specifications, supplier costs, weights and media must be verified individually.')+'<label for="enh-import-file">Choose CSV</label><input id="enh-import-file" type="file" accept=".csv,text/csv" onchange="enhImportFile(this)"><label for="enh-import-text">CSV content</label><textarea id="enh-import-text" rows="5">template_sku,sku,title,retail,bulk,volume,moq,pack,threshold\nFAN-01,NEW-FAN-001,New fan draft,6000,5000,4500,10,5,50</textarea><p id="enh-import-status" role="status"></p><div id="enh-import-preview"></div><div class="actions">'+button('Validate and preview','enhImportPreviewForm()','secondary')+button('Create reviewed-input drafts','enhImportCommit()')+'</div>');}
const enhBulkAdmin=adminPage;adminPage=id=>enhBulkAdmin(id)+(id==='A07'?enhImportPanel():'');


const enhRenderBase=render;render=()=>{const id=location.hash.slice(1);if(authBooted&&id.startsWith('C')&&authSession('customer')){const user=authSession('customer');const room=state.authActiveCustomerId===user.id?state:state.authCustomerSpaces?.[user.id];const current=room?.orderSnapshot?.id;const order=current&&enhInit().orders[current];state.dispatch=order?.customerId===user.id&&!!order.shipment?.dispatched;state.delivery=order?.customerId===user.id&&!!order.shipment?.delivered;}enhRenderBase();};


const enhEvidenceFiles=new Map();
function enhEvidencePanel(t){const user=authSession('worker'),editable=jobsActor(t)&&['Accepted','In progress','Needs correction'].includes(t.status);return card('Job evidence attachments',(editable?'<label for="enh-evidence-files">Attach photos, PDF reports or video (up to 10 MB each)</label><input id="enh-evidence-files" type="file" multiple accept="image/jpeg,image/png,image/webp,application/pdf,video/mp4" onchange="enhAttachEvidence(&quot;'+t.id+'&quot;,this)">':'')+(t.attachments||[]).map(a=>row(esc(a.name),esc(a.type)+' · '+Math.ceil(a.size/1024)+' KB'+(enhEvidenceFiles.has(a.id)?'<a class="button secondary" href="'+esc(enhEvidenceFiles.get(a.id))+'" target="_blank" rel="noopener noreferrer">Preview</a>':'<small>Reattach after refresh for a file preview.</small>'))).join('')+note('Files are previewed on this device for this session. Metadata and submission references are retained; durable private uploads will be connected later.'));}
function enhAttachEvidence(id,input){const t=state.ops.tasks.find(t=>t.id===id),u=t&&jobsActor(t);if(!u||!['Accepted','In progress','Needs correction'].includes(t.status))return;const files=Array.from(input.files||[]);if((t.attachments?.length||0)+files.length>10||files.some(f=>f.size>10*1024*1024||!['image/jpeg','image/png','image/webp','application/pdf','video/mp4'].includes(f.type))){toast('Use at most 10 JPEG, PNG, WebP, PDF or MP4 files under 10 MB each.');return;}t.attachments=t.attachments||[];for(const f of files){const a={id:'EVID-'+authRandom(8),name:f.name,type:f.type,size:f.size,workerId:u.id,staffId:t.staffId,at:Date.now()};t.attachments.push(a);enhEvidenceFiles.set(a.id,URL.createObjectURL(f));}persist();jobsOpen(id);toast('Evidence attached locally. Add its reference or a report summary when submitting.');}
const enhEvidenceOpen=jobsOpen;jobsOpen=id=>{enhEvidenceOpen(id);const t=state.ops.tasks.find(t=>t.id===id);if(t&&(jobsManager()||jobsActor(t)))$('modal').innerHTML+=enhEvidencePanel(t);};opsOpenTask=jobsOpen;
const enhEvidenceTransition=jobsTransition;jobsTransition=(id,action,data={})=>{const t=state.ops.tasks.find(t=>t.id===id);const r=enhEvidenceTransition(id,action,data);if(r.ok&&action==='submit'){t.submissions[0].attachments=(t.attachments||[]).filter(a=>a.staffId===t.staffId&&a.workerId===authSession('worker')?.id).map(a=>authCopy(a));persist();}return r;};
function enhExportCatalog(){if(!jobsManager())return;const headers=['template_sku','sku','title','retail','bulk','volume','moq','pack','threshold'];const quote=v=>{let raw=String(v);if(typeof v==='string'&&/^[=+@\-\t\r]/.test(raw))raw=String.fromCharCode(39)+raw;return '"'+raw.replaceAll('"','""')+'"';};const csv=headers.join(',')+'\n'+products.map(p=>[p.id,p.id,p.name,p.retail,p.bulk,p.volume,p.moq,p.pack,p.volumeThreshold].map(quote).join(',')).join('\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='ChinaLowCost-Catalog.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Catalog exported. Change SKU values before importing as new drafts.');}
const enhExportPanel=enhImportPanel;enhImportPanel=()=>enhExportPanel()+(jobsManager()?button('Export current catalog CSV','enhExportCatalog()','secondary'):'');

const authReady=authInitialize();
render();
